WITH with_windows AS (SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, AVG(credit_limit) OVER (PARTITION BY segment ORDER BY signup_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS credit_limit_avg_5, CORR(credit_limit, age) OVER (PARTITION BY segment) AS corr_credit_limit_age, LAST_VALUE(age) IGNORE NULLS OVER (PARTITION BY segment, country ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_age, LAG(age, 1, 0) OVER (PARTITION BY city, segment ORDER BY credit_limit, id) AS prev_age FROM customers), cleaned AS (SELECT *, last_known_age * credit_limit_avg_5 AS last_known_age_times_credit_limit_avg_5, CONCAT(country, ', ', email) AS country_email, COALESCE(segment, 'N/A') AS segment_filled FROM with_windows WHERE signup_date > DATE '2023-07-12'), enriched AS (SELECT *, AVG(last_known_age_times_credit_limit_avg_5) OVER (PARTITION BY country ORDER BY age, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS last_known_age_times_credit_limit_avg_5_avg_5, ROW_NUMBER() OVER (PARTITION BY segment, city ORDER BY prev_age DESC, id) AS row_seq FROM cleaned), metrics AS (SELECT *, AVG(last_known_age_times_credit_limit_avg_5) OVER w_grp AS last_known_age_times_credit_limit_avg_5_avg_3, FIRST_VALUE(corr_credit_limit_age) IGNORE NULLS OVER (PARTITION BY segment, city ORDER BY last_known_age_times_credit_limit_avg_5, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_corr_credit_limit_age, PERCENT_RANK() OVER w_grp_2 AS last_known_age_percent_rank, FIRST_VALUE(row_seq) IGNORE NULLS OVER (PARTITION BY segment ORDER BY last_known_age_times_credit_limit_avg_5, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_row_seq, ROW_NUMBER() OVER (PARTITION BY city ORDER BY last_known_age_times_credit_limit_avg_5_avg_5 DESC, id) AS row_seq_2 FROM enriched WINDOW w_grp AS (PARTITION BY city ORDER BY last_known_age_times_credit_limit_avg_5_avg_5, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_grp_2 AS (PARTITION BY segment ORDER BY last_known_age DESC)) SELECT id, name, email, country, segment, signup_date, is_active, age, credit_limit_avg_5, CASE WHEN segment RLIKE '^(SMB|Consumer)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS segment_zone FROM metrics ORDER BY signup_date DESC NULLS FIRST;
